using ModelContextProtocol.Server;
using System.ComponentModel;

namespace McpHttpServer.Tools;

[McpServerToolType]
public static class EchoTool
{
    [McpServerTool, Description("Echoes back the provided message.")]
    public static string Echo([Description("The message to echo")] string message)
        => $"Echo: {message}";

    [McpServerTool, Description("Returns the current server time in UTC.")]
    public static string GetServerTime()
        => $"Server time: {DateTime.UtcNow:O}";
}

using ModelContextProtocol.Server;
using System.ComponentModel;

namespace McpHttpServer.Resources;

[McpServerResourceType]
public static class ConfigResource
{
    [McpServerResource(
        UriTemplate = "config://app/settings",
        Name = "App Settings",
        Description = "Returns the current application configuration data.",
        MimeType = "application/json")]
    public static string GetAppSettings()
    {
        return """
        {
            "environment": "production",
            "version": "1.0.0",
            "features": {
                "darkMode": true,
                "analytics": false,
                "maxRetries": 3
            },
            "supportedLocales": ["en-US", "fr-FR", "de-DE"]
        }
        """;
    }

    [McpServerResource(
        UriTemplate = "config://app/health",
        Name = "Health Check",
        Description = "Returns the server health status.",
        MimeType = "application/json")]
    public static string GetHealthStatus()
    {
        return $$"""
        {
            "status": "healthy",
            "uptime": "{{DateTime.UtcNow:O}}",
            "checks": {
                "database": "ok",
                "cache": "ok"
            }
        }
        """;
    }
}

arguments.new_str:
using McpHttpServer.Tools;
using McpHttpServer.Resources;

var builder = WebApplication.CreateBuilder(args);

builder.Services
    .AddMcpServer()
    .WithHttpTransport()
    .WithTools<EchoTool>()
    .WithResources<ConfigResource>();

var app = builder.Build();

app.MapMcp();

app.Run();

